#!/usr/bin/env node
// Dependency-free replica of .codex/skills/email-api/scripts/email-contacts.js
// (the skill helper cannot run because 'minimist' is not installed).
// Same request: GET <BASE_URL>/contacts with X-API-Key / X-User-Email headers.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok === '--api-key' && i + 1 < argv.length) {
      args['api-key'] = argv[++i];
    } else if (tok === '--user-email' && i + 1 < argv.length) {
      args['user-email'] = argv[++i];
    }
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];
  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }
  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

getContacts(parseArgs(process.argv.slice(2)))
  .then((result) => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch((error) => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
